                    'sections' => [
                        ['t'=>'explanation','h'=>'Bu nedir?','b'=>"Almancada \"sen\" için iki ayrı biçim vardır:\n\ndu → samimi: arkadaş, aile, çocuklar, yakın iş arkadaşları\nSie → resmi: tanımadığın yetişkinler, müşteriler, amirler, memurlar, doktorlar\n\nSie her zaman BÜYÜK harfle yazılır ve çoğul fiil alır."],
                        ['t'=>'rule','h'=>'Kural','b'=>"Fiil çekimi değişir:\n\nWie heißt du? → Adın ne? (samimi)\nWie heißen Sie? → Adınız ne? (resmi)\n\nWoher kommst du? / Woher kommen Sie?\nWo wohnst du? / Wo wohnen Sie?\n\nSie ile fiil her zaman mastar biçimindedir: kommen, wohnen, heißen."],
                        ['t'=>'tr_contrast','h'=>'Türkçeden farkı','b'=>"Türkçede \"siz\" kullanımı esnektir; yaşça büyük birine \"sen\" demek bazen kabul edilir. Almanya'da ise kural nettir: TANIMADIĞIN HER YETİŞKİNE \"Sie\" denir. Karşı taraf \"Wir können uns duzen\" (birbirimize sen diyebiliriz) demeden \"du\"ya geçilmez."],
                        ['t'=>'usage','h'=>'Gerçek hayatta kullanım','b'=>"İş yerinde bazı Alman şirketleri herkesin \"du\" kullandığı bir kültür benimser. İlk gün amirin sana \"Ich bin Thomas, wir sagen hier alle du\" derse artık \"du\" kullanabilirsin. Emin değilsen \"Sie\" ile başla; bu hiçbir zaman kaba görünmez.",'c'=>1],
                        ['t'=>'common_mistake','h'=>'En sık yapılan hata','b'=>"Sie kullanırken fiili tekil çekmek: \"Wie heißt Sie?\" yanlıştır. Doğrusu \"Wie heißen Sie?\"dir.",'c'=>1],
                    ],
                    'vocab' => ['Herr','Frau','Wie geht es Ihnen?','Wie geht\'s?','Woher kommen Sie?'],
                    'exercises' => [
