                        ['type'=>'multiple_choice','mode'=>'recall','skill'=>'sie_du','q'=>'"Nerede oturuyorsunuz?" (resmi) nasıl denir?','a'=>'Wo wohnen Sie?','opts'=>['Wo wohnen Sie?','Wo wohnst Sie?','Wo wohnt Sie?','Wo wohnen du?'],'exp'=>'Sie ile fiil mastar biçimindedir: wohnen.','vg'=>'siedu-conjugate'],
                        ['type'=>'multiple_choice','mode'=>'recall','skill'=>'sie_du','q'=>'Yakın arkadaşına "Nereden geliyorsun?" nasıl sorarsın?','a'=>'Woher kommst du?','opts'=>['Woher kommst du?','Woher kommen Sie?','Woher kommt du?','Woher kommen du?'],'exp'=>'du ile fiil -st eki alır: du kommst.','vg'=>'siedu-conjugate'],
                        ['type'=>'sentence_correction','mode'=>'production','skill'=>'sie_du','q'=>'Bu cümledeki hatayı düzelt: "Wie heißt Sie?"','a'=>'Wie heißen Sie?','exp'=>'Sie ile fiil çoğul/mastar biçimindedir: heißen.','vg'=>'siedu-correct'],
                        ['type'=>'multiple_choice','mode'=>'application','skill'=>'sie_du','q'=>'Almanya\'da bir kişiye "du" demeye ne zaman geçilir?','a'=>'Karşı taraf teklif ettiğinde','opts'=>['Karşı taraf teklif ettiğinde','İkinci görüşmede otomatik olarak','Yaş küçükse hemen','Aynı işte çalışıyorsanız hemen'],'exp'=>'Genellikle yaşça büyük veya kıdemli olan kişi "du"yu teklif eder. Sen kendiliğinden geçmezsin.','vg'=>'siedu-culture'],
